    val arabicRegex = Regex("([\\u0600-\\u06FF\\u0750-\\u077F\\u08A0-\\u08FF\\uFB50-\\uFDFF\\uFE70-\\uFEFF]+[\\u0600-\\u06FF\\u0750-\\u077F\\u08A0-\\u08FF\\uFB50-\\uFDFF\\uFE70-\\uFEFF0-9\\s{}«».,:؛؟\\-]*[\\u0600-\\u06FF\\u0750-\\u077F\\u08A0-\\u08FF\\uFB50-\\uFDFF\\uFE70-\\uFEFF]+)|([\\u0600-\\u06FF\\u0750-\\u077F\\u08A0-\\u08FF\\uFB50-\\uFDFF\\uFE70-\\uFEFF]+)")
    var lastIndex = 0
    try {
        arabicRegex.findAll(text).forEach { matchResult ->
            text.substring(lastIndex, matchResult.range.first)
            lastIndex = matchResult.range.last + 1
        }
        text.substring(lastIndex)
        println("All good!")
    } catch (e: Exception) {
        println(e)
    }
